options.getOption:
// Reports per day, and a brush that sets the map's time window.
//
// Dragging across the histogram writes the window, snapped to whole UTC days,
// to `mapFrom` and `mapTo` as ISO 8601: the same pair the map's time player
// writes, so the map moves its own window to match, and the counters, the
// type and state charts and the table follow it. Moving the map's player
// moves the brush here. Clearing the brush hands back the whole week.
//
// The histogram does not filter on its own window. Two query frames feed it:
// `all` (grey, every report in the map's extent; columns `bin`, `n`) and
// `selected` (what the type and state pickers leave, split by type in the
// map's colours; columns `bin`, `type`, `n`). `bin` is the day's UTC midnight
// in epoch ms. This is assets/brush-histogram.js with time bins, ISO
// variables and stacked types.
// @constants begin
const LO = 'mapFrom';
const HI = 'mapTo';
const STEP = 86400000;
const UNIT = 'reports';
const COLORS = {
  'Flash Flood': '#1f5fa9',
  Flood: '#6baed6',
  Hail: '#8c6bb1',
  Lightning: '#e7b416',
  Tornado: '#d62728',
  Wildfire: '#e8642f',
  'Wind Damage': '#2b8c5d',
  'Wind Gust': '#7fcaa0',
  Snow: '#17becf',
};
const OTHER = '#9e9e9e';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;

const frameOf = (refId) => context.panel.data.series.find((f) => f.refId === refId);
const col = (frame, name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const allFrame = frameOf('all');
const selFrame = frameOf('selected');
const allBins = col(allFrame, 'bin').map(Number);
const allCounts = col(allFrame, 'n').map(Number);
const selBins = col(selFrame, 'bin').map(Number);
const selTypes = col(selFrame, 'type').map(String);
const selCounts = col(selFrame, 'n').map(Number);
const types = [...new Set(selTypes)].sort((a, b) => (b in COLORS) - (a in COLORS) || a.localeCompare(b));

const starts = allBins.concat(selBins);
const first = starts.length ? Math.min(...starts) : Math.floor(Date.now() / STEP) * STEP - 7 * STEP;
const last = starts.length ? Math.max(...starts) : Math.floor(Date.now() / STEP) * STEP;
const domain = [first, last + STEP];
// One category per day for the bars: ECharts stacks bars by their position
// in the data, which a value axis does not line up. A second, hidden time
// axis over the same span carries the brush, so it can cover whole days
// edge to edge rather than run between bar centres.
const days = Array.from({ length: Math.round((last - first) / STEP) + 1 }, (_, i) => first + i * STEP);
const cell = new Map(selBins.map((b, i) => [b + '|' + selTypes[i], selCounts[i]]));
const allByDay = new Map(allBins.map((b, i) => [b, allCounts[i]]));

const day = (ms) => new Date(ms).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
const iso = (ms) => new Date(ms).toISOString();

// Whole days only: a window that cuts a bar in two would count part of it.
const snap = (range) => {
  const lo = Math.max(domain[0], Math.floor(range[0] / STEP) * STEP);
  const hi = Math.min(domain[1], Math.max(Math.ceil(range[1] / STEP) * STEP, lo + STEP));
  return [lo, hi];
};
const drawBrush = (range) =>
  chart.dispatchAction({ type: 'brush', areas: range ? [{ brushType: 'lineX', xAxisIndex: 1, coordRange: range }] : [] });
// Empty variables would leave the map where it is (it waits out blanks), so a
// cleared brush writes the whole span instead: the map widens to match.
const publish = (range) => {
  const [lo, hi] = range ?? domain;
  location.partial({ ['var-' + LO]: iso(lo), ['var-' + HI]: iso(hi - 1) }, true);
};

chart.off('brushEnd');
chart.off('brush');
chart.on('brushEnd', (event) => {
  const area = event.areas[0];
  if (!area || !area.coordRange) {
    publish(undefined);
    return;
  }
  const range = snap(area.coordRange);
  publish(range);
  setTimeout(() => drawBrush(range), 0);
});
chart.on('brush', (event) => {
  if (event.command === 'clear') {
    publish(undefined);
  }
});

// The window from the variables: a shared link, or the map's player. One that
// covers the whole span is no window at all, and draws no brush.
const windowOf = () => {
  const params = new URLSearchParams(location.getLocation().search);
  const lo = Date.parse(params.get('var-' + LO) ?? '');
  const hi = Date.parse(params.get('var-' + HI) ?? '');
  if (!Number.isFinite(lo) || !Number.isFinite(hi) || hi <= lo) {
    return null;
  }
  return lo <= domain[0] + STEP && hi >= domain[1] - STEP ? null : [Math.max(lo, domain[0]), Math.min(hi, domain[1])];
};

// The days outside the window fade, as on the map's own timeline.
const series = (window) => {
  const fade = (b) => (window && (b + STEP <= window[0] || b > window[1]) ? 0.3 : 1);
  return [
    {
      id: 'all',
      name: 'All in view',
      type: 'bar',
      barWidth: '94%',
      silent: true,
      itemStyle: { color: 'rgba(128, 128, 128, 0.22)' },
      data: days.map((b) => allByDay.get(b) ?? 0),
    },
    ...types.map((type) => ({
      id: type,
      name: type,
      type: 'bar',
      stack: 'selected',
      barWidth: '94%',
      barGap: '-100%',
      itemStyle: { color: COLORS[type] ?? OTHER },
      data: days.map((b) => ({ value: cell.get(b + '|' + type) ?? null, itemStyle: { opacity: fade(b) } })),
    })),
  ];
};

// Every redraw wipes the brush, and the map's player changes the variables
// without changing this panel's data: draw both back from the variables.
let drawn = JSON.stringify(windowOf());
const redraw = () => {
  chart.dispatchAction({ type: 'takeGlobalCursor', key: 'brush', brushOption: { brushType: 'lineX', brushMode: 'single' } });
  drawBrush(windowOf());
};
setTimeout(redraw, 0);
const stop = location.getHistory().listen(() => {
  const now = windowOf();
  if (JSON.stringify(now) !== drawn && !chart.isDisposed()) {
    drawn = JSON.stringify(now);
    chart.setOption({ series: series(now) });
    redraw();
  }
});

const option = {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 24, top: 30, bottom: 4, containLabel: true },
  legend: { top: 2, left: 0, icon: 'rect', itemWidth: 10, itemHeight: 10, textStyle: { color: muted, fontSize: 11 }, data: types },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'none' },
    formatter: (items) => {
      const at = days[items[0].dataIndex];
      const rows = items
        .filter((it) => it.value != null)
        .map((it) => `${it.marker}${it.seriesName}: <b>${it.value}</b>`)
        .join('<br/>');
      return `${day(at)} (UTC), ${UNIT}<br/>${rows}`;
    },
  },
  toolbox: {
    right: 8,
    top: 0,
    itemSize: 14,
    feature: { brush: { type: ['lineX', 'clear'], title: { lineX: 'Select days', clear: 'Back to the whole week' } } },
  },
  brush: {
    xAxisIndex: 1,
    seriesIndex: [],
    brushType: 'lineX',
    brushMode: 'single',
    transformable: true,
    brushStyle: { color: 'rgba(128, 128, 128, 0.12)', borderColor: muted, borderWidth: 1 },
  },
  xAxis: [
    { type: 'category', data: days.map(day), axisTick: { show: false }, axisLabel: { color: muted } },
    { type: 'value', min: domain[0], max: domain[1], show: false },
  ],
  yAxis: { type: 'value', axisLabel: { color: muted }, splitLine: { lineStyle: { opacity: 0.15 } } },
  series: series(windowOf()),
};

return { version: 2, option, unsubscribe: stop };

