options.getOption:
// Reports by event type, in the map's colours: the chart is the map's legend.
//
// Clicking a bar adds that type to the `type` variable, or takes it out if it
// is already in; taking out the last one goes back to All. The map, the
// counters, the state chart, the histogram and the table all filter on `type`;
// this chart does not, so the types left out stay in grey as context. The
// query frame has columns `key` (the type) and `n` (reports), already
// filtered by the map's extent, its time window and the state.
// @constants begin
const VAR = 'type';
const COLORS = {
  'Flash Flood': '#1f5fa9',
  Flood: '#6baed6',
  Hail: '#8c6bb1',
  Lightning: '#e7b416',
  Tornado: '#d62728',
  Wildfire: '#e8642f',
  'Wind Damage': '#2b8c5d',
  'Wind Gust': '#7fcaa0',
  Snow: '#17becf',
};
const OTHER = '#9e9e9e';
const UNIT = 'reports';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;

const frame = context.panel.data.series.find((f) => f.refId === 'D');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
// ECharts draws a category axis bottom up: reversed, the largest is on top.
const keys = col('key').map(String).reverse();
const counts = col('n').map((v) => (v == null ? null : Number(v))).reverse();

// The variable's values, read from the URL, where the panel's own writes land
// first; null means All.
const picked = () => {
  const values = new URLSearchParams(location.getLocation().search).getAll('var-' + VAR);
  return values.length === 0 || values.includes('$__all') || values.includes('All') ? null : values;
};
const toggle = (key) => {
  const now = picked();
  const next = !now ? [key] : now.includes(key) ? now.filter((v) => v !== key) : [...now, key];
  location.partial({ ['var-' + VAR]: next.length ? next : '$__all' }, true);
};

chart.off('click');
chart.on('click', (event) => toggle(keys[event.dataIndex]));

const bars = (chosen) =>
  keys.map((key, i) => ({
    value: counts[i],
    itemStyle: {
      color: chosen && !chosen.includes(key) ? 'rgba(128, 128, 128, 0.22)' : COLORS[key] ?? OTHER,
      borderRadius: [0, 3, 3, 0],
    },
  }));

// A click changes the variable but not this query, so the panel is not drawn
// again: repaint the bars from the URL whenever it changes.
let drawn = JSON.stringify(picked());
const stop = location.getHistory().listen(() => {
  const now = picked();
  if (JSON.stringify(now) !== drawn && !chart.isDisposed()) {
    drawn = JSON.stringify(now);
    chart.setOption({ series: [{ id: 'bars', data: bars(now) }] });
  }
});

const option = {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 36, top: 8, bottom: 22, containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => `${items[0].name}: <b>${items[0].value}</b> ${UNIT}<br/><span style="opacity:.7">click to filter</span>`,
  },
  xAxis: {
    type: 'value',
    name: UNIT,
    nameLocation: 'middle',
    nameGap: 22,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  yAxis: { type: 'category', data: keys, axisTick: { show: false }, axisLabel: { color: text, fontSize: 11 } },
  series: [
    {
      id: 'bars',
      type: 'bar',
      barWidth: '70%',
      barMaxWidth: 24,
      cursor: 'pointer',
      data: bars(picked()),
      label: { show: true, position: 'right', color: muted, fontSize: 11 },
    },
  ],
};

return { version: 2, option, unsubscribe: stop };

