options.getOption:
// The states with most reports, each bar split by event type in the map's
// colours.
//
// Clicking a bar adds that state to the `state` variable, or takes it out if
// it is already in; taking out the last one goes back to All. The map, the
// counters, the type chart, the histogram and the table filter on `state`;
// this chart does not, so the states left out stay, faded, as context. The
// query frame has columns `key` (the state), `type` and `n` (reports), already
// filtered by the map's extent, its time window and the type.
// @constants begin
const VAR = 'state';
const TOP = 15;
const COLORS = {
  'Flash Flood': '#1f5fa9',
  Flood: '#6baed6',
  Hail: '#8c6bb1',
  Lightning: '#e7b416',
  Tornado: '#d62728',
  Wildfire: '#e8642f',
  'Wind Damage': '#2b8c5d',
  'Wind Gust': '#7fcaa0',
  Snow: '#17becf',
};
const OTHER = '#9e9e9e';
const UNIT = 'reports';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;

const frame = context.panel.data.series.find((f) => f.refId === 'E');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const states = col('key').map(String);
const kinds = col('type').map(String);
const counts = col('n').map(Number);

const totals = new Map();
states.forEach((s, i) => totals.set(s, (totals.get(s) ?? 0) + counts[i]));
// The largest on top: a category axis draws bottom up.
const keys = [...totals.keys()].sort((a, b) => totals.get(b) - totals.get(a)).slice(0, TOP).reverse();
const types = [...new Set(kinds)].sort((a, b) => (a in COLORS) - (b in COLORS) || a.localeCompare(b)).reverse();
const cell = new Map(states.map((s, i) => [s + '|' + kinds[i], counts[i]]));

const picked = () => {
  const values = new URLSearchParams(location.getLocation().search).getAll('var-' + VAR);
  return values.length === 0 || values.includes('$__all') || values.includes('All') ? null : values;
};
const toggle = (key) => {
  const now = picked();
  const next = !now ? [key] : now.includes(key) ? now.filter((v) => v !== key) : [...now, key];
  location.partial({ ['var-' + VAR]: next.length ? next : '$__all' }, true);
};

chart.off('click');
chart.on('click', (event) => toggle(keys[event.dataIndex]));

const series = (chosen) =>
  types.map((type) => ({
    id: type,
    name: type,
    type: 'bar',
    stack: 'reports',
    barWidth: '70%',
    barMaxWidth: 24,
    cursor: 'pointer',
    itemStyle: { color: COLORS[type] ?? OTHER },
    data: keys.map((key) => ({
      value: cell.get(key + '|' + type) ?? null,
      itemStyle: { opacity: chosen && !chosen.includes(key) ? 0.2 : 1 },
    })),
  }));

// A click changes the variable but not this query: repaint from the URL.
let drawn = JSON.stringify(picked());
const stop = location.getHistory().listen(() => {
  const now = picked();
  if (JSON.stringify(now) !== drawn && !chart.isDisposed()) {
    drawn = JSON.stringify(now);
    chart.setOption({ series: series(now) });
  }
});

const option = {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 16, top: 8, bottom: 22, containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => {
      const rows = items
        .filter((it) => it.value != null)
        .reverse()
        .map((it) => `${it.marker}${it.seriesName}: <b>${it.value}</b>`)
        .join('<br/>');
      return `<b>${items[0].name}</b> · ${totals.get(items[0].name)} ${UNIT}<br/>${rows}<br/><span style="opacity:.7">click to filter</span>`;
    },
  },
  xAxis: {
    type: 'value',
    name: UNIT,
    nameLocation: 'middle',
    nameGap: 22,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  yAxis: { type: 'category', data: keys, axisTick: { show: false }, axisLabel: { color: text, fontSize: 11 } },
  series: series(picked()),
};

return { version: 2, option, unsubscribe: stop };

